CREATE OR REPLACE FUNCTION public.guardar_firma_diploma(_curso uuid,_instructor uuid,_nombre text,_cargo text,_firma text,_motivo text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE prev public.curso_diploma_config; nid uuid; inicial boolean:=auth.role()='service_role' AND current_setting('tracea.firma_inicial',true)='1'; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(_curso::text,820)); SELECT * INTO prev FROM public.curso_diploma_config WHERE curso_id=_curso ORDER BY version DESC LIMIT 1; IF NOT coalesce(inicial,false) AND (auth.uid() IS NULL OR NOT coalesce(public.is_super_admin() OR (prev.instructor_user_id=auth.uid() AND _instructor=prev.instructor_user_id),false)) THEN RAISE EXCEPTION 'Solo el super administrador o el instructor cambia la firma del diploma'; END IF; IF inicial AND prev.id IS NOT NULL THEN RETURN prev.id; END IF; IF length(btrim(coalesce(_motivo,'')))<5 THEN RAISE EXCEPTION 'Motivo obligatorio (mínimo 5 caracteres)'; END IF; IF coalesce(_firma,'') NOT LIKE 'data:image/png;base64,%' OR length(_firma)>2000000 OR btrim(coalesce(_nombre,''))='' OR btrim(coalesce(_cargo,''))='' THEN RAISE EXCEPTION 'Selecciona una firma PNG y completa nombre y cargo'; END IF; IF _instructor IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_instructor AND activo) THEN RAISE EXCEPTION 'Instructor no disponible'; END IF; PERFORM set_config('tracea.firma_diploma_rpc','1',true); INSERT INTO public.curso_diploma_config(curso_id,version,instructor_user_id,instructor_nombre,instructor_cargo,firma_png,motivo,created_by) VALUES(_curso,coalesce(prev.version,0)+1,_instructor,btrim(_nombre),btrim(_cargo),_firma,btrim(_motivo),coalesce(auth.uid(),_instructor)) RETURNING id INTO nid; INSERT INTO public.audit_trail(user_id,org_id,tabla,registro_id,accion,motivo,valor_anterior,valor_nuevo,origen) VALUES(coalesce(auth.uid(),_instructor),public.get_user_org_id(),'curso_diploma_config',nid::text,'FIRMA_DIPLOMA_CONFIGURADA',btrim(_motivo),CASE WHEN prev.id IS NOT NULL THEN to_jsonb(prev)-'firma_png' END,jsonb_build_object('curso_id',_curso,'version',coalesce(prev.version,0)+1,'instructor_nombre',_nombre,'instructor_user_id',_instructor,'firma_sha256',encode(sha256(convert_to(_firma,'UTF8')),'hex')),CASE WHEN inicial THEN 'sistema' ELSE 'usuario' END); RETURN nid; END $$;
CREATE OR REPLACE FUNCTION public.inicializar_firma_diploma(_curso uuid,_instructor uuid,_firma text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Solo el servidor prellena el activo autorizado'; END IF; PERFORM set_config('tracea.firma_inicial','1',true); RETURN public.guardar_firma_diploma(_curso,_instructor,'Ing. Jaime David Del Castillo Couret','Instructor — TRACEA Academy',_firma,'S-1: restauración del activo autorizado existente'); END $$;
REVOKE ALL ON FUNCTION public.inicializar_firma_diploma(uuid,uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.inicializar_firma_diploma(uuid,uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.marcar_password_temporal(_usuario uuid,_org uuid,_actor uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Solo el servidor registra contraseñas temporales'; END IF; INSERT INTO public.usuario_acceso_temporal(user_id,org_id,pendiente,asignada_por) VALUES(_usuario,_org,true,_actor) ON CONFLICT(user_id) DO UPDATE SET pendiente=true,asignada_en=now(),cambiada_en=NULL,asignada_por=_actor,org_id=_org; INSERT INTO public.audit_trail(user_id,org_id,tabla,registro_id,accion,motivo,valor_nuevo) VALUES(_actor,_org,'usuario_acceso_temporal',_usuario::text,'TEMPORAL_ASIGNADA','Alta con contraseña temporal',jsonb_build_object('pendiente',true)); END $$;
CREATE OR REPLACE FUNCTION public.confirmar_password_temporal(_usuario uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Solo el servidor confirma el cambio de contraseña'; END IF; UPDATE public.usuario_acceso_temporal SET pendiente=false,cambiada_en=now() WHERE user_id=_usuario AND pendiente RETURNING org_id INTO org; IF FOUND THEN INSERT INTO public.audit_trail(user_id,org_id,tabla,registro_id,accion,motivo,valor_anterior,valor_nuevo) VALUES(_usuario,org,'usuario_acceso_temporal',_usuario::text,'CONTRASENA_CAMBIADA','Primer acceso: cambio obligatorio',jsonb_build_object('pendiente',true),jsonb_build_object('pendiente',false)); END IF; END $$;